const crypto = require("crypto")

function base64UrlEncode(input) {
  return Buffer.from(JSON.stringify(input)).toString("base64url")
}

function base64UrlEncodeBuffer(input) {
  return Buffer.from(input).toString("base64url")
}

function parseExpiresIn(expiresIn) {
  if (typeof expiresIn === "number") {
    return expiresIn
  }

  const match = String(expiresIn || "").trim().match(/^(\d+)([smhd])$/i)
  if (!match) {
    return 0
  }

  const amount = Number(match[1])
  const unit = match[2].toLowerCase()
  const multipliers = { s: 1000, m: 60 * 1000, h: 60 * 60 * 1000, d: 24 * 60 * 60 * 1000 }
  return amount * (multipliers[unit] || 0)
}

function sign(payload, secret, options = {}) {
  const header = { alg: "HS256", typ: "JWT" }
  const now = Math.floor(Date.now() / 1000)
  const fullPayload = { ...payload }

  if (options.expiresIn) {
    fullPayload.exp = now + Math.floor(parseExpiresIn(options.expiresIn) / 1000)
  }

  const encodedHeader = base64UrlEncode(header)
  const encodedPayload = base64UrlEncode(fullPayload)
  const data = `${encodedHeader}.${encodedPayload}`
  const signature = crypto.createHmac("sha256", String(secret)).update(data).digest("base64url")

  return `${data}.${signature}`
}

function verify(token, secret) {
  const parts = String(token).split(".")

  if (parts.length !== 3) {
    throw new Error("Invalid token")
  }

  const [encodedHeader, encodedPayload, signature] = parts
  const data = `${encodedHeader}.${encodedPayload}`
  const expectedSignature = crypto.createHmac("sha256", String(secret)).update(data).digest("base64url")

  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature))) {
    throw new Error("Invalid signature")
  }

  const payload = JSON.parse(Buffer.from(encodedPayload, "base64url").toString("utf8"))

  if (payload.exp && Math.floor(Date.now() / 1000) >= payload.exp) {
    throw new Error("Token expired")
  }

  return payload
}

function decode(token) {
  const parts = String(token).split(".")
  if (parts.length < 2) {
    return null
  }

  return JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8"))
}

module.exports = {
  decode,
  sign,
  verify
}
